workspace "Library" "A small public library system." {
    model {
        patron = person "Patron" "Borrows books at the library."
        library = softwareSystem "Library" "Manages books and loans." {
            catalog = container "Catalog Web App" "Lets patrons browse the catalogue." "Python"
            circulation = container "Circulation Service" "Records loans and returns." "Java"
        }
        patron -> catalog "Browses the catalogue through" "HTTPS"
        catalog -> circulation "Records loans via" "gRPC"
    }
    views {
        systemContext library "SystemContext" {
            include *
            autoLayout
        }
    }
}

workspace "Bookshop" "A simple online bookshop" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "A customer who browses the book catalogue and places orders"

        bookshop = softwareSystem "Bookshop" "An online bookshop where customers browse books and place orders" {
            webStore = container "Web Store" "The web application customers use to browse the catalogue and place orders" "Java/Spring Boot"
            orderProcessor = container "Order Processor" "Validates and fulfils customer orders" "Java/Spring Boot"
        }

        customer -> bookshop.webStore "browses the catalogue and places orders via" "HTTPS"
        bookshop.webStore -> bookshop.orderProcessor "sends new orders to" "JSON/HTTP"
    }

    views {
        systemContext bookshop "BookshopContext" "System context for the Bookshop" {
            include *
            autoLayout
            title "System Context for Bookshop"
        }
    }
}

